 * Users Routes — Worker lookup for repair assignment UI.
 */

import { Hono } from 'hono'
import { getActiveWorkers } from '../services/users.service.js'

const usersRoutes = new Hono()

// ---------------------------------------------------------------------------
// GET /users — List active workers for dropdown selectors
//
// Returns compact worker data (id, name, role) sorted by name.
// Only returns active workers (isActive=true).
// ---------------------------------------------------------------------------

usersRoutes.get('/', async () => {
  const workers = await getActiveWorkers()
  return new Response(JSON.stringify(workers), {
    headers: { 'Content-Type': 'application/json' },
  })
})

export default usersRoutes

/**
 * Users Service — Worker lookup for repair assignment and display.
 */

import { eq } from 'drizzle-orm'
import { db } from '../db/index.js'
import { users } from '../db/schema.js'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/** Compact worker shape for dropdown selectors (name + role only) */
export interface WorkerOption {
  id: string
  name: string
  role: 'mechanic' | 'manager'
}

// ---------------------------------------------------------------------------
// Functions
// ---------------------------------------------------------------------------

/**
 * List all active workers, suitable for populating a worker assignment dropdown.
 * Returns workers sorted by name for consistent display order.
 */
export async function getActiveWorkers(): Promise<WorkerOption[]> {
  const rows = await db
    .select({
      id: users.id,
      name: users.name,
      role: users.role,
    })
    .from(users)
    .where(eq(users.isActive, true))
    .orderBy(users.name)

  return rows as unknown as WorkerOption[]
}

/**
 * CustomerFormDialog — Radix Dialog modal for creating and editing customers.
 *
 * Single component handles both modes:
 * - Create mode: title "New Customer", empty form, calls POST /api/customers
 * - Edit mode: title "Edit Customer", pre-populated fields, calls PATCH /api/customers/:id
 *
 * Features:
 * - Type selector (private/company) with conditional required fields
 * - Address section with searchable postal code + street comboboxes
 * - Auto-fill city from selected postal code (with manual override)
 * - Client-side Zod validation before submission
 * - Inline error display for validation errors
 */

import { useCallback, useEffect, useState } from 'react'
import * as DialogPrimitive from '@radix-ui/react-dialog'
import { X } from 'lucide-react'
import { cn } from '@/shared/lib/utils.js'
import { Button } from '@/components/ui/button.js'
import { Input } from '@/components/ui/input.js'
import { Label } from '@/components/ui/label.js'
import { createCustomer, updateCustomer } from '../api.js'
import type { CustomerDetail } from '../types.js'
import { PostalCodeCombobox } from './PostalCodeCombobox.js'
import { StreetCombobox } from './StreetCombobox.js'
import type { PostalCodeResult, StreetResult } from '../hooks/useAddressSearch.js'

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** EU country options for the dropdown (ISO 2-letter codes) */
const COUNTRY_OPTIONS = [
  { value: 'BE', label: 'Belgium' },
  { value: 'DE', label: 'Germany' },
  { value: 'FR', label: 'France' },
  { value: 'NL', label: 'Netherlands' },
  { value: 'LU', label: 'Luxembourg' },
  { value: 'AT', label: 'Austria' },
  { value: 'IT', label: 'Italy' },
  { value: 'ES', label: 'Spain' },
  { value: 'PT', label: 'Portugal' },
  { value: 'IE', label: 'Ireland' },
  { value: 'FI', label: 'Finland' },
  { value: 'SE', label: 'Sweden' },
  { value: 'DK', label: 'Denmark' },
  { value: 'PL', label: 'Poland' },
  { value: 'CZ', label: 'Czech Republic' },
] as const

// ---------------------------------------------------------------------------
// Form State Shape
// ---------------------------------------------------------------------------

interface CustomerFormData {
  type: 'private' | 'company'
  firstName: string
  lastName: string
  companyName: string
  vatId: string
  phone: string
  email: string
  street: string
  number: string
  bus: string
  postalCode: string
  city: string
  country: string
}

/** Default empty form state */
const createEmptyForm = (): CustomerFormData => ({
  type: 'private',
  firstName: '',
  lastName: '',
  companyName: '',
  vatId: '',
  phone: '',
  email: '',
  street: '',
  number: '',
  bus: '',
  postalCode: '',
  city: '',
  country: 'BE',
})

/** Populate form from an existing customer (edit mode) */
function populateForm(customer: CustomerDetail): CustomerFormData {
  return {
    type: customer.type,
    firstName: customer.firstName ?? '',
    lastName: customer.lastName ?? '',
    companyName: customer.companyName ?? '',
    vatId: customer.vatId ?? '',
    phone: customer.phone ?? '',
    email: customer.email ?? '',
    street: customer.street ?? '',
    number: customer.number ?? '',
    bus: customer.bus ?? '',
    postalCode: customer.postalCode ?? '',
    city: customer.city ?? '',
    country: customer.country ?? 'BE',
  }
}

// ---------------------------------------------------------------------------
// Validation Helpers (mirrors shared Zod schemas)
// ---------------------------------------------------------------------------

interface FormErrors {
  /** Field-level errors keyed by field name (empty when no field errors) */
  fields: Record<string, string>
  /** General form-level error message */
  general?: string
}

/** Validate the form data against business rules. Returns null if valid. */
function validateForm(data: CustomerFormData): FormErrors | null {
  const fields: Record<string, string> = {}

  // Type branching — required fields
  if (data.type === 'private') {
    if (!data.firstName.trim()) {
      fields.firstName = 'First name is required for private customers'
    }
    if (!data.lastName.trim()) {
      fields.lastName = 'Last name is required for private customers'
    }
  } else {
    // company
    if (!data.companyName.trim()) {
      fields.companyName = 'Company name is required for company customers'
    }
  }

  // Address conditional validation — if street is provided, number/postalCode/city must also be present
  const hasStreet = data.street.trim().length > 0
  if (hasStreet) {
    if (!data.number.trim()) {
      fields.number = 'Number is required when street is provided'
    }
    if (!data.postalCode.trim()) {
      fields.postalCode = 'Postal code is required when street is provided'
    }
    if (!data.city.trim()) {
      fields.city = 'City is required when street is provided'
    }
  }

  // Phone/email loose validation — min 1 char if provided, max 50
  if (data.phone && data.phone.length > 50) {
    fields.phone = 'Phone must be at most 50 characters'
  }
  if (data.email && data.email.length > 50) {
    fields.email = 'Email must be at most 50 characters'
  }

  return Object.keys(fields).length > 0 ? { fields } : null
}

/** Helper to create an empty errors object */
const emptyErrors: FormErrors = { fields: {} }

/** Build the API payload from form data, stripping empty strings and setting defaults */
function buildPayload(data: CustomerFormData): Record<string, unknown> {
  const payload: Record<string, unknown> = { type: data.type }

  // Always include country (defaults to BE)
  if (data.country.trim()) {
    payload.country = data.country.trim()
  } else {
    payload.country = 'BE'
  }

  // Type-branching fields — only include relevant ones
  if (data.type === 'private') {
    if (data.firstName.trim()) payload.firstName = data.firstName.trim()
    if (data.lastName.trim()) payload.lastName = data.lastName.trim()
  } else {
    if (data.companyName.trim()) payload.companyName = data.companyName.trim()
  }

  // Optional fields — only include non-empty values
  if (data.vatId.trim()) payload.vatId = data.vatId.trim()
  if (data.phone.trim()) payload.phone = data.phone.trim()
  if (data.email.trim()) payload.email = data.email.trim()

  // Address fields — only include non-empty values
  if (data.street.trim()) payload.street = data.street.trim()
  if (data.number.trim()) payload.number = data.number.trim()
  if (data.bus.trim()) payload.bus = data.bus.trim()
  if (data.postalCode.trim()) payload.postalCode = data.postalCode.trim()
  if (data.city.trim()) payload.city = data.city.trim()

  return payload
}

// ---------------------------------------------------------------------------
// Field Component — reusable form field with label and inline error
// ---------------------------------------------------------------------------

interface FormFieldProps {
  label: string
  name: string
  value: string
  onChange: (name: string, value: string) => void
  error?: string
  placeholder?: string
  type?: 'text' | 'email' | 'tel'
  required?: boolean
}

function FormField({
  label,
  name,
  value,
  onChange,
  error,
  placeholder,
  type = 'text',
}: FormFieldProps) {
  return (
    <div className="space-y-1.5">
      <Label htmlFor={name} className={cn(error && 'text-destructive')}>
        {label}
      </Label>
      <Input
        id={name}
        name={name}
        type={type}
        value={value}
        onChange={(e) => onChange(name, e.target.value)}
        placeholder={placeholder}
        className={cn(error && 'border-destructive focus-visible:ring-destructive')}
      />
      {error && (
        <p className="text-xs text-destructive">{error}</p>
      )}
    </div>
  )
}

// ---------------------------------------------------------------------------
// Country Select — native select with EU country options + free text fallback
// ---------------------------------------------------------------------------

interface CountrySelectProps {
  value: string
  onChange: (value: string) => void
  error?: string
}

function CountrySelect({ value, onChange, error }: CountrySelectProps) {
  return (
    <div className="space-y-1.5">
      <Label htmlFor="country" className={cn(error && 'text-destructive')}>
        Country
      </Label>
      <select
        id="country"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className={cn(
          'flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50',
          error && 'border-destructive focus-visible:ring-destructive'
        )}
      >
        {COUNTRY_OPTIONS.map((option) => (
          <option key={option.value} value={option.value}>
            {option.label} ({option.value})
          </option>
        ))}
        {/* Free text fallback — custom code */}
        <option value="__custom__">Other (enter manually)</option>
      </select>
      {error && (
        <p className="text-xs text-destructive">{error}</p>
      )}
    </div>
  )
}

// ---------------------------------------------------------------------------
// Main Dialog Component
// ---------------------------------------------------------------------------

interface CustomerFormDialogProps {
  /** Whether the dialog is open */
  open: boolean
  /** Callback when dialog opens/closes */
  onOpenChange: (open: boolean) => void
  /** Existing customer for edit mode; null for create mode */
  editingCustomer?: CustomerDetail | null
  /** Called after successful save — typically to refresh the list */
  onSaveSuccess: () => void
}

export function CustomerFormDialog({
  open,
  onOpenChange,
  editingCustomer,
  onSaveSuccess,
}: CustomerFormDialogProps) {
  const isEditMode = editingCustomer != null

  // Form state — resets when dialog opens/closes or mode changes
  const [formData, setFormData] = useState<CustomerFormData>(createEmptyForm)
  const [errors, setErrors] = useState<FormErrors | null>(null)
  const [isSubmitting, setIsSubmitting] = useState(false)

  // Address search state — separate from formData to power comboboxes.
  const [postalCodeResult, setPostalCodeResult] = useState<PostalCodeResult | null>(null)
  const [streetResult, setStreetResult] = useState<StreetResult | null>(null)

  // Reset form when dialog opens or customer changes
  useEffect(() => {
    if (open) {
      const newForm = editingCustomer ? populateForm(editingCustomer) : createEmptyForm()
      setFormData(newForm)

      // In edit mode, reconstruct postal code and street result objects so the
      // comboboxes display their saved values instead of showing empty.
      if (editingCustomer && newForm.postalCode) {
        setPostalCodeResult({
          code: newForm.postalCode,
          name: newForm.postalCode, // Display only the code
          municipality: newForm.city ?? '',
        })
      } else {
        setPostalCodeResult(null)
      }

      // Reconstruct street result if customer has a saved address — displays it
      // as readonly with a clear button, allowing users to search for a new one.
      if (editingCustomer && newForm.street) {
        setStreetResult({
          name: newForm.street,
          postalCode: newForm.postalCode ?? '',
          municipality: newForm.city ?? '',
        })
      } else {
        setStreetResult(null)
      }

      setErrors(null)
      setIsSubmitting(false)
    }
  }, [open, editingCustomer])

  // -----------------------------------------------------------------------
  // Field change handler
  // -----------------------------------------------------------------------

  const handleFieldChange = useCallback((name: string, value: string) => {
    setFormData((prev) => ({ ...prev, [name]: value }))
    // Clear field error when user starts typing
    if (errors && errors.fields[name]) {
      setErrors({ ...errors, fields: { ...errors.fields, [name]: '' } })
    }
  }, [errors])

  // -----------------------------------------------------------------------
  // Type change handler — resets type-specific fields on switch
  // -----------------------------------------------------------------------

  const handleTypeChange = useCallback((type: 'private' | 'company') => {
    setFormData((prev) => ({ ...prev, type }))
    // Clear type-specific errors when switching
    if (errors && (errors.fields.firstName || errors.fields.lastName || errors.fields.companyName)) {
      setErrors({
        ...errors,
        fields: {
          ...errors.fields,
          firstName: '',
          lastName: '',
          companyName: '',
        },
      })
    }
  }, [errors])

  // -----------------------------------------------------------------------
  // Country change handler — handles free text fallback
  // -----------------------------------------------------------------------

  const handleCountryChange = useCallback((value: string) => {
    if (value === '__custom__') {
      setFormData((prev) => ({ ...prev, country: '' }))
    } else {
      setFormData((prev) => ({ ...prev, country: value }))
    }
  }, [])

  // -----------------------------------------------------------------------
  // Postal code selection handler
  // -----------------------------------------------------------------------

  const handlePostalCodeSelect = useCallback(
    (result: PostalCodeResult | null) => {
      if (result) {
        // Set display name to code only (city is handled by separate field).
        setPostalCodeResult({ ...result, name: result.code })
        setFormData((prev) => ({
          ...prev,
          postalCode: result.code,
          city: result.municipality, // auto-fill from postal code
        }))
        // Street becomes valid for the new postal code — clear previous selection.
        setStreetResult(null)
      } else {
        setPostalCodeResult(null)
        setFormData((prev) => ({
          ...prev,
          postalCode: '',
          city: prev.city ? '' : prev.city, // only clear if still auto-filled
        }))
        // Clear street too since it was scoped to the old postal code.
        setStreetResult(null)
      }
    },
    [],
  )

  // -----------------------------------------------------------------------
  // Street selection handler
  // -----------------------------------------------------------------------

  const handleStreetSelect = useCallback((result: StreetResult | null) => {
    if (result) {
      setStreetResult(result)
      setFormData((prev) => ({ ...prev, street: result.name }))
    } else {
      setStreetResult(null)
      setFormData((prev) => ({ ...prev, street: '' }))
    }
  }, [])

  // -----------------------------------------------------------------------
  // City reset handler — clears auto-fill and allows free text editing.
  // -----------------------------------------------------------------------

  const handleCityReset = useCallback(() => {
    setFormData((prev) => ({ ...prev, city: '' }))
  }, [])

  // -----------------------------------------------------------------------
  // Submit handler
  // -----------------------------------------------------------------------

  const handleSubmit = useCallback(async (e: React.FormEvent) => {
    e.preventDefault()

    // Validate before submission
    const validationErrors = validateForm(formData)
    if (validationErrors) {
      setErrors(validationErrors)
      return
    }

    setIsSubmitting(true)
    setErrors(emptyErrors)

    try {
      const payload = buildPayload(formData)

      if (isEditMode && editingCustomer) {
        await updateCustomer(editingCustomer.id, payload)
      } else {
        await createCustomer(payload)
      }

      onSaveSuccess()
      onOpenChange(false)
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to save customer'
      setErrors({ fields: {}, general: message })
    } finally {
      setIsSubmitting(false)
    }
  }, [formData, isEditMode, editingCustomer, onSaveSuccess, onOpenChange])

  // -----------------------------------------------------------------------
  // Dialog close handler — resets state
  // -----------------------------------------------------------------------

  const handleClose = useCallback(() => {
    setFormData(createEmptyForm())
    setPostalCodeResult(null)
    setStreetResult(null)
    setErrors(null)
    setIsSubmitting(false)
    onOpenChange(false)
  }, [onOpenChange])

  // -----------------------------------------------------------------------
  // Render
  // -----------------------------------------------------------------------

  return (
    <DialogPrimitive.Root open={open} onOpenChange={handleClose}>
      <DialogPrimitive.Portal>
        <DialogPrimitive.Overlay className="fixed inset-0 z-50 bg-black/80 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0" />
        <DialogPrimitive.Content
          className={cn(
            'fixed left-[50%] top-[50%] z-50 w-full max-w-lg translate-x-[-50%] translate-y-[-50%] gap-4 border bg-background p-6 shadow-lg duration-200 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%] data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%] sm:rounded-lg',
            'max-h-[90vh] overflow-y-auto'
          )}
        >
          {/* Header */}
          <div className="flex items-center justify-between">
            <DialogPrimitive.Title className="text-lg font-semibold leading-none tracking-tight">
              {isEditMode ? 'Edit Customer' : 'New Customer'}
            </DialogPrimitive.Title>
            <DialogPrimitive.Close asChild>
              <Button variant="ghost" size="sm" className="h-6 w-6 p-0">
                <X className="h-4 w-4" />
                <span className="sr-only">Close</span>
              </Button>
            </DialogPrimitive.Close>
          </div>

          {/* General error */}
          {errors?.general && (
            <div className="rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700 dark:border-red-800 dark:bg-red-900/20 dark:text-red-300">
              {errors.general}
            </div>
          )}

          {/* Form */}
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Type selector */}
            <fieldset className="space-y-2">
              <legend className="text-sm font-medium">Customer type</legend>
              <div className="flex gap-4">
                <label className="inline-flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    name="type"
                    value="private"
                    checked={formData.type === 'private'}
                    onChange={() => handleTypeChange('private')}
                    className="h-4 w-4 border-gray-300 text-blue-600 focus:ring-blue-500"
                  />
                  <span className="text-sm">Private</span>
                </label>
                <label className="inline-flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    name="type"
                    value="company"
                    checked={formData.type === 'company'}
                    onChange={() => handleTypeChange('company')}
                    className="h-4 w-4 border-gray-300 text-purple-600 focus:ring-purple-500"
                  />
                  <span className="text-sm">Company</span>
                </label>
              </div>
            </fieldset>

            {/* Type-specific fields */}
            {formData.type === 'private' ? (
              <div className="grid grid-cols-2 gap-4">
                <FormField
                  label="First name"
                  name="firstName"
                  value={formData.firstName}
                  onChange={handleFieldChange}
                  error={errors?.fields.firstName}
                  placeholder="e.g. Jan"
                />
                <FormField
                  label="Last name"
                  name="lastName"
                  value={formData.lastName}
                  onChange={handleFieldChange}
                  error={errors?.fields.lastName}
                  placeholder="e.g. Kowalski"
                />
              </div>
            ) : (
              <FormField
                label="Company name"
                name="companyName"
                value={formData.companyName}
                onChange={handleFieldChange}
                error={errors?.fields.companyName}
                placeholder="e.g. Acme Corp"
              />
            )}

            {/* Optional: VAT ID (company) / Side business (private) */}
            <FormField
              label={formData.type === 'company' ? 'VAT ID' : 'Side business name'}
              name="vatId"
              value={formData.vatId}
              onChange={handleFieldChange}
              placeholder={formData.type === 'company' ? 'e.g. BE0123456789' : 'Optional'}
            />

            {/* Contact info */}
            <div className="grid grid-cols-2 gap-4">
              <FormField
                label="Phone"
                name="phone"
                value={formData.phone}
                onChange={handleFieldChange}
                error={errors?.fields.phone}
                placeholder="+32 470 ..."
                type="tel"
              />
              <FormField
                label="Email"
                name="email"
                value={formData.email}
                onChange={handleFieldChange}
                error={errors?.fields.email}
                placeholder="customer@example.com"
                type="email"
              />
            </div>

            {/* Address section */}
            <fieldset className="space-y-3 border-t pt-4">
              <legend className="text-sm font-medium">Address</legend>

              {/* Street + Number row */}
              <div className="grid grid-cols-2 gap-4">
                <StreetCombobox
                  postalCode={formData.postalCode || null}
                  value={streetResult}
                  onValueChange={handleStreetSelect}
                  className="h-10"
                />
                <FormField
                  label="Number"
                  name="number"
                  value={formData.number}
                  onChange={handleFieldChange}
                  error={errors?.fields.number}
                  placeholder="e.g. 12"
                />
              </div>

              {/* Bus + Postal code + City row */}
              <div className="grid grid-cols-3 gap-4">
                <FormField
                  label="Bus"
                  name="bus"
                  value={formData.bus}
                  onChange={handleFieldChange}
                  placeholder="e.g. A"
                />

                {/* Postal code — searchable combobox */}
                <div className="space-y-1.5">
                  <Label htmlFor="postalCode">Postal code</Label>
                  <div className="h-10">
                    <PostalCodeCombobox
                      value={postalCodeResult}
                      onValueChange={handlePostalCodeSelect}
                      className="w-full"
                    />
                  </div>
                  {errors?.fields.postalCode && (
                    <p className="text-xs text-destructive">{errors.fields.postalCode}</p>
                  )}
                </div>

                {/* City — auto-filled from postal code, with reset button */}
                <div className="space-y-1.5">
                  <Label htmlFor="city" className={cn(formData.city && !postalCodeResult && 'text-muted-foreground')}>
                    {formData.city && !postalCodeResult ? 'City (edited)' : 'City'}
                  </Label>
                  <div className="relative h-10">
                    <Input
                      id="city"
                      name="city"
                      value={formData.city}
                      onChange={(e) => handleFieldChange('city', e.target.value)}
                      placeholder="Auto-filled from postal code"
                      className={cn(
                        'pr-7', // space for reset button
                        errors?.fields.city && 'border-destructive focus-visible:ring-destructive'
                      )}
                    />
                    {/* Reset auto-fill — only show when there's a value but no active selection */}
                    {formData.city && !postalCodeResult && (
                      <button
                        type="button"
                        onClick={handleCityReset}
                        className="absolute right-2 top-1/2 -translate-y-1/2 p-0.5 rounded-full hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
                        tabIndex={-1}
                      >
                        <X className="h-3 w-3" />
                        <span className="sr-only">Reset auto-fill</span>
                      </button>
                    )}
                  </div>
                  {errors?.fields.city && (
                    <p className="text-xs text-destructive">{errors.fields.city}</p>
                  )}
                </div>
              </div>

              {/* Country — select with free text fallback */}
              <CountrySelect
                value={formData.country || '__custom__'}
                onChange={handleCountryChange}
                error={undefined} // country is always valid (defaults to BE)
              />
            </fieldset>

            {/* Footer actions */}
            <div className="flex justify-end gap-2 pt-2">
              <Button variant="outline" type="button" onClick={handleClose} disabled={isSubmitting}>
                Cancel
              </Button>
              <Button type="submit" disabled={isSubmitting}>
                {isSubmitting ? 'Saving...' : isEditMode ? 'Save changes' : 'Create customer'}
              </Button>
            </div>
          </form>
        </DialogPrimitive.Content>
      </DialogPrimitive.Portal>
    </DialogPrimitive.Root>
  )
}

import { z } from 'zod'

// ---------------------------------------------------------------------------
// Customer type enum
// ---------------------------------------------------------------------------

export const customerTypeSchema = z.enum(['private', 'company'])

/** A customer type discriminator */
export type CustomerType = z.infer<typeof customerTypeSchema>

// ---------------------------------------------------------------------------
// Address fields (shared between create and update)
// ---------------------------------------------------------------------------

const addressFields = {
  street: z.string().max(200).optional(),
  number: z.string().max(20).optional(),
  bus: z.string().max(10).optional(),
  postalCode: z.string().max(20).optional(),
  city: z.string().max(100).optional(),
  country: z.string().max(5).default('BE'),
}

// ---------------------------------------------------------------------------
// Create input schemas — type branching via discriminated union
// ---------------------------------------------------------------------------

/** Private customer creation input */
const createPrivateSchema = z.object({
  id: z.string().uuid('id must be a valid UUID').optional(),
  type: z.literal('private'),
  firstName: z.string().min(1, 'firstName is required for private customers').max(100),
  lastName: z.string().min(1, 'lastName is required for private customers').max(100),
  companyName: z.string().max(200).optional(),
  vatId: z.string().max(50).optional(),
  phone: z.string().min(1).max(50).optional(),
  email: z.string().min(1).max(50).optional(),
  ...addressFields,
})

/** Company customer creation input */
const createCompanySchema = z.object({
  id: z.string().uuid('id must be a valid UUID').optional(),
  type: z.literal('company'),
  firstName: z.string().max(100).optional(),
  lastName: z.string().max(100).optional(),
  companyName: z.string().min(1, 'companyName is required for company customers').max(200),
  vatId: z.string().max(50).optional(),
  phone: z.string().min(1).max(50).optional(),
  email: z.string().min(1).max(50).optional(),
  ...addressFields,
})

/** Union of create schemas — type branching at validation time */
export const createCustomerSchema = z.discriminatedUnion('type', [
  createPrivateSchema,
  createCompanySchema,
])

/** Input for creating a new customer.
 * Note: country is optional here (defaults to 'BE' at runtime via Zod).
 */
export type CreateCustomerInput = Omit<z.infer<typeof createCustomerSchema>, 'country'> & { country?: string }

// ---------------------------------------------------------------------------
// Update input schema — partial fields, at least one required
// ---------------------------------------------------------------------------

const updateBaseFields = {
  firstName: z.string().min(1).max(100).optional(),
  lastName: z.string().min(1).max(100).optional(),
  companyName: z.string().min(1).max(200).optional(),
  vatId: z.string().max(50).nullable().optional(),
  phone: z.string().min(1).max(50).optional(),
  email: z.string().min(1).max(50).optional(),
  ...addressFields,
}

/** Update input — at least one meaningful field must be provided.
 * Excludes country (has default) and optional fields that may auto-populate.
 */
const updatableFields = [
  'firstName', 'lastName', 'companyName', 'vatId',
  'phone', 'email', 'street', 'number', 'bus',
  'postalCode', 'city'
] as const

export const updateCustomerSchema = z.object(updateBaseFields).refine(
  data => updatableFields.some(key => data[key] !== undefined),
  { message: 'At least one field must be provided for update' }
)

/** Input for updating an existing customer.
 * Note: country is optional here (defaults to 'BE' at runtime via Zod).
 */
export type UpdateCustomerInput = Omit<z.infer<typeof updateCustomerSchema>, 'country'> & { country?: string }

// ---------------------------------------------------------------------------
// Address conditional validation helper
// If street is provided, number/postalCode/city must also be present
// ---------------------------------------------------------------------------

/**
 * Validate address fields — if street is set, number, postalCode, and city are required.
 */
export function validateAddress(input: Record<string, unknown>): { valid: boolean; errors?: string[] } {
  const errors: string[] = []

  if (input.street && !input.number) {
    errors.push('number is required when street is provided')
  }
  if (input.street && !input.postalCode) {
    errors.push('postalCode is required when street is provided')
  }
  if (input.street && !input.city) {
    errors.push('city is required when street is provided')
  }

  return errors.length > 0 ? { valid: false, errors } : { valid: true }
}

/**
 * Customers — API client functions.
 */

import type { CustomerPaginatedResponse, CustomerDetail } from './types.js'

const BASE_URL = '' // relative to current origin

// ---------------------------------------------------------------------------
// Management List (paginated + searchable)
// ---------------------------------------------------------------------------

export async function fetchCustomers({
  search,
  page = 1,
  pageSize = 25,
}: {
  search?: string
  page?: number
  pageSize?: number
}): Promise<CustomerPaginatedResponse> {
  const params = new URLSearchParams()

  if (search !== undefined && search !== '') {
    params.set('search', search)
  }
  params.set('page', String(page))
  params.set('pageSize', String(pageSize))

  const response = await fetch(`${BASE_URL}/api/customers?${params}`)

  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw new Error((body as { error?: string }).error ?? `Failed to load customers: ${response.status}`)
  }

  return response.json() as Promise<CustomerPaginatedResponse>
}

